// Additional, independently implemented management tools informed by the public feature guide.
function extras(g){g.vehicles??=[];g.tactics??=[];g.backstory??='';g.privateNotes??='';return g}function campaignExtras(c){c.triumphs??=[];c.houseRules??='';return c}data.gangs.forEach(extras);data.campaigns.forEach(campaignExtras);
const previousRating=rating;rating=function(g){return previousRating(g)+(g?.vehicles||[]).reduce((sum,v)=>sum+n(v.cost)+(v.equipment||[]).reduce((a,e)=>a+n(e.cost),0),0)};
const previousFighterDetail=fighterDetail;fighterDetail=function(f){previousFighterDetail(f);let pane=document.querySelector('.modal-body');if(!pane)return;pane.insertAdjacentHTML('beforeend',`<div class="extra-detail"><h3>추가 관리</h3><div class="actions"><button class="btn small" data-ext="copy-fighter" data-id="${f.id}">파이터 복제</button><button class="btn small" data-ext="fighter-note" data-id="${f.id}">배경 이야기</button></div>${f.effects?.length?`<h3>효과 삭제</h3>${f.effects.map(e=>`<button class="btn small" data-ext="remove-effect" data-id="${f.id}" data-sub="${e.id}">${esc(e.name)} ×</button>`).join(' ')}`:''}${f.skills?.length?`<h3>스킬 삭제</h3>${f.skills.map((s,i)=>`<button class="btn small" data-ext="remove-skill" data-id="${f.id}" data-sub="${i}">${esc(s)} ×</button>`).join(' ')}`:''}</div>`)};
function vehiclesTab(g){extras(g);return `<div class="toolbar"><h2 class="section-title">차량 (${g.vehicles.length})</h2>${btn('＋ 차량 등록','unused','primary').replace('data-action="unused"','data-ext="new-vehicle"')}</div>${g.vehicles.length?`<div class="grid">${g.vehicles.map(v=>`<article class="card">${chip(v.status||'Active',v.status==='Active'?'':'red')}<h3>${esc(v.name)}</h3><p>${esc(v.type||'차량')} · 조종자 ${esc(g.fighters.find(f=>f.id===v.crew)?.name||'미배정')}</p><div class="meta"><span><b>${fmt(v.cost)}</b>차량 비용</span><span><b>${(v.equipment||[]).length}</b>장비</span></div><div class="actions"><button class="btn small" data-ext="vehicle-detail" data-id="${v.id}">상세</button><button class="btn small" data-ext="edit-vehicle" data-id="${v.id}">수정</button><button class="btn small danger" data-ext="delete-vehicle" data-id="${v.id}">삭제</button></div></article>`).join('')}</div>`:empty('▣','차량이 없습니다','차량과 조종자, 장비, 손상을 기록하세요.',`<button class="btn primary" data-ext="new-vehicle">차량 등록</button>`)}`}
function tacticsTab(g){extras(g);return `<div class="toolbar"><h2 class="section-title">전술 카드 (${g.tactics.length})</h2><button class="btn primary" data-ext="new-tactic">＋ 카드 추가</button></div>${g.tactics.length?`<div class="grid">${g.tactics.map(t=>`<article class="card">${chip(t.source||'사용자 정의','gold')}<h3>${esc(t.name)}</h3><p>${esc(t.effect||'효과 메모 없음')}</p><button class="btn small danger" data-ext="delete-tactic" data-id="${t.id}">삭제</button></article>`).join('')}</div>`:empty('▤','전술 카드가 없습니다','카드 이름과 효과를 직접 기록하세요.')}`}
function gangNotesTab(g){extras(g);return `<div class="split"><div class="card"><h3>갱 이야기</h3><p style="white-space:pre-wrap">${esc(g.backstory||'기록 없음')}</p><button class="btn small" data-ext="edit-gang-story">수정</button></div><div class="card"><h3>개인 메모</h3><p style="white-space:pre-wrap">${esc(g.privateNotes||'기록 없음')}</p><button class="btn small" data-ext="edit-gang-private">수정</button><p class="footer-note">이 앱의 모든 데이터는 현재 브라우저에 저장됩니다.</p></div></div>`}
function gangCampaignTab(g){let memberships=data.campaigns.flatMap(c=>c.members.filter(m=>m.gangId===g.id).map(m=>({campaign:c,member:m})));return `<div class="toolbar"><h2 class="section-title">참가 캠페인</h2><button class="btn" data-action="nav-campaigns">캠페인 보기</button></div>${memberships.length?`<div class="grid">${memberships.map(({campaign:c,member:m})=>`<article class="card">${chip(m.role)}<h3>${esc(c.name)}</h3><p>${esc(c.phase)} · ${c.territories.filter(t=>t.gangId===g.id).length}개 영토</p><button class="btn small" data-open-campaign="${c.id}">열기</button></article>`).join('')}</div>`:empty('◈','참가 캠페인이 없습니다','캠페인 페이지에서 이 갱을 등록하세요.')}`}
gangPage=function(){const g=gang();if(!g)return gangsPage();extras(g);const tabs=[['fighters','갱 / 파이터'],['stash','창고'],['vehicles','차량'],['campaign-link','캠페인'],['gang-notes','노트'],['tactics','전술 카드'],['resources','자원'],['logs','기록']];return heading('GANG DOSSIER',esc(g.name),`${esc(g.faction)} · ${esc(g.edition)} · ${esc(g.alignment)}`,btn('갱 수정','edit-current-gang')+`<button class="btn" data-ext="copy-gang">복제</button><button class="btn" data-ext="print-gang">인쇄</button>`+btn('삭제','delete-gang','danger'))+`<div class="stats">${stat('갱 평점',fmt(rating(g)),'파이터 + 장비 + 차량')}${stat('크레딧',fmt(g.credits),'사용 가능')}${stat('명성',fmt(g.reputation),'Reputation')}${stat('파이터',g.fighters.length,`${g.fighters.filter(f=>f.status==='Active').length}명 활동 중`)}</div><div class="tabs">${tabs.map(([v,t])=>`<button data-tab="${v}" class="${data.tab===v?'active':''}">${t}</button>`).join('')}</div>${({fighters:()=>fightersTab(g),stash:()=>stashTab(g),vehicles:()=>vehiclesTab(g),'campaign-link':()=>gangCampaignTab(g),'gang-notes':()=>gangNotesTab(g),tactics:()=>tacticsTab(g),resources:()=>resourcesTab(g),logs:()=>logsTab(g)})[data.tab]?.()||fightersTab(g)}`};
function mapTab(c){campaignExtras(c);const dots=c.territories.map((t,i)=>{let x=Math.min(95,Math.max(5,Number(t.x??(18+i*21)%90))),y=Math.min(90,Math.max(10,Number(t.y??(23+i*17)%80)));return `<button class="map-dot" style="left:${x}%;top:${y}%" title="${esc(t.name)}" data-ext="map-edit" data-id="${t.id}"><span>⬡</span><small>${esc(t.name)}</small></button>`}).join('');return `<div class="toolbar"><h2 class="section-title">캠페인 지도</h2><button class="btn" data-campaign-tab="territories">영토 관리</button></div><div class="map-board">${dots||'<div class="map-empty">영토를 추가하면 지도에 표시됩니다.</div>'}</div><p class="footer-note">영토를 눌러 지도 위치를 조정하세요. 지도는 캠페인별로 저장됩니다.</p>`}
function triumphsTab(c){campaignExtras(c);return `<div class="toolbar"><h2 class="section-title">성과 / Triumphs</h2><button class="btn primary" data-ext="new-triumph">＋ 성과 기록</button></div>${c.triumphs.length?`<div class="grid">${c.triumphs.map(t=>`<article class="card">${chip(data.gangs.find(g=>g.id===t.gangId)?.name||'캠페인')}<h3>${esc(t.name)}</h3><p>${esc(t.notes||'')}</p><button class="btn small danger" data-ext="delete-triumph" data-id="${t.id}">삭제</button></article>`).join('')}</div>`:empty('★','성과 기록이 없습니다','캠페인 성과와 수상 갱을 기록하세요.')}`}
function campaignNotesTab(c){return `<div class="split"><div class="card"><h3>캠페인 스토리</h3><p style="white-space:pre-wrap">${esc(c.notes||'기록 없음')}</p><button class="btn small" data-ext="edit-campaign-notes">수정</button></div><div class="card"><h3>하우스 룰</h3><p style="white-space:pre-wrap">${esc(c.houseRules||'기록 없음')}</p><button class="btn small" data-ext="edit-house-rules">수정</button></div></div>`}
campaignPage=function(){const c=campaign();if(!c)return campaignsPage();campaignExtras(c);const tabs=[['members','캠페인'],['territories','영토'],['battles','전투'],['campaign-notes','노트'],['map','지도'],['triumphs','성과']];const ct=data.campaignTab||'members';return heading('CAMPAIGN RECORD',esc(c.name),`${esc(c.edition)} · ${esc(c.phase)}`,btn('캠페인 수정','edit-campaign')+btn('삭제','delete-campaign','danger'))+`<div class="stats">${stat('참가 갱',c.members.length,'플레이어 지정')}${stat('영토',c.territories.length,'등록된 영토')}${stat('전투',c.battles.length,'기록된 전투')}${stat('최고 평점',fmt(Math.max(0,...c.members.map(m=>rating(data.gangs.find(g=>g.id===m.gangId))))),'참가 갱 기준')}</div><div class="tabs">${tabs.map(([v,t])=>`<button data-campaign-tab="${v}" class="${ct===v?'active':''}">${t}</button>`).join('')}</div>${({members:()=>membersTab(c),territories:()=>territoriesTab(c),battles:()=>battlesTab(c),'campaign-notes':()=>campaignNotesTab(c),map:()=>mapTab(c),triumphs:()=>triumphsTab(c)})[ct]?.()||membersTab(c)}`};
function vehicleForm(v){let g=gang();extras(g);formModal(v?'차량 수정':'차량 등록',field('name','차량 이름',v?.name,'text','required')+field('type','유형',v?.type||'Vehicle','text','required')+field('cost','비용 (cr)',v?.cost??0,'number','min="0"')+select('status','상태',['Active','Damaged','Destroyed','Retired'],v?.status||'Active')+select('crew','조종자',[['','미배정'],...g.fighters.map(f=>[f.id,f.name])],v?.crew||'')+textarea('notes','차량 메모',v?.notes),x=>{if(v)Object.assign(v,{...x,cost:n(x.cost)});else{v={id:id(),...x,cost:n(x.cost),equipment:[],damages:[]};g.vehicles.push(v)}log(g,`${v.name} 차량 ${x?'정보를 저장했습니다.':'등록했습니다.'}`);save()})}
function vehicleDetail(v){let g=gang();showModal(esc(v.name),`<p>${chip(v.status,v.status==='Active'?'':'red')} · ${esc(v.type)} · ${fmt(v.cost)} cr</p><p>조종자: ${esc(g.fighters.find(f=>f.id===v.crew)?.name||'미배정')}</p><h3>장비</h3><div class="mini-list">${(v.equipment||[]).map(e=>`<div class="mini-row">${esc(e.name)} · ${fmt(e.cost)} cr <button class="btn small danger" data-ext="delete-vehicle-equipment" data-id="${v.id}" data-sub="${e.id}">삭제</button></div>`).join('')||'없음'}</div><h3>지속 손상</h3><div class="mini-list">${(v.damages||[]).map(d=>`<div class="mini-row">${esc(d.name)} <button class="btn small danger" data-ext="repair-vehicle" data-id="${v.id}" data-sub="${d.id}">수리</button></div>`).join('')||'없음'}</div><p style="white-space:pre-wrap">${esc(v.notes||'메모 없음')}</p><div class="actions"><button class="btn small" data-ext="add-vehicle-equipment" data-id="${v.id}">＋ 장비</button><button class="btn small" data-ext="add-vehicle-damage" data-id="${v.id}">＋ 손상</button></div>`,'닫기',()=>true)}
const previousEditTerritory=editTerritory;editTerritory=function(t){let c=campaign();formModal(t?'영토 수정':'영토 추가',field('name','영토 이름',t?.name,'text','required')+select('gangId','소유 갱',gangOptions('',true),t?.gangId||'')+field('x','지도 X 위치 (0–100)',t?.x??50,'number','min="0" max="100"')+field('y','지도 Y 위치 (0–100)',t?.y??50,'number','min="0" max="100"')+textarea('notes','메모',t?.notes),v=>{let value={name:v.name,gangId:v.gangId,x:n(v.x),y:n(v.y),notes:v.notes};if(t)Object.assign(t,value);else c.territories.push({id:id(),...value});save()})};
function cloneGang(g){let copy=structuredClone(g);copy.id=id();copy.name=g.name+' 사본';copy.fighters.forEach(f=>{f.id=id();f.equipment.forEach(e=>e.id=id());f.effects.forEach(e=>e.id=id())});copy.stash.forEach(e=>e.id=id());(copy.vehicles||[]).forEach(v=>{v.id=id();v.crew='';v.equipment.forEach(e=>e.id=id());v.damages.forEach(d=>d.id=id())});(copy.tactics||[]).forEach(t=>t.id=id());copy.logs=[];log(copy,'갱을 복제했습니다.');data.gangs.push(copy);data.selectedGang=copy.id;data.tab='fighters';save()}
function printGang(g){let w=window.open('','_blank');if(!w){alert('팝업을 허용하면 인쇄할 수 있습니다.');return}let body=`<h1>${esc(g.name)}</h1><p>${esc(g.faction)} · ${esc(g.edition)} · 평점 ${fmt(rating(g))} · 크레딧 ${fmt(g.credits)}</p><h2>파이터</h2>${g.fighters.map(f=>`<section><h3>${esc(f.name)} — ${esc(f.type)} (${fmt(f.cost)} cr)</h3><p>${esc(f.status)} · XP ${fmt(f.xp)} · 처치 ${fmt(f.kills)}</p><p>${Object.entries(f.stats).map(([k,v])=>`${k} ${v}`).join(' · ')}</p><p>장비: ${f.equipment.map(e=>esc(e.name)).join(', ')||'없음'}</p><p>스킬: ${f.skills.map(esc).join(', ')||'없음'}</p></section>`).join('')}<h2>창고</h2><p>${g.stash.map(e=>esc(e.name)).join(', ')||'없음'}</p><h2>차량</h2><p>${(g.vehicles||[]).map(v=>esc(v.name)).join(', ')||'없음'}</p>`;w.document.write(`<html><head><title>${esc(g.name)}</title><style>body{font:14px Arial;max-width:850px;margin:auto;padding:20px;color:#111}h1{border-bottom:3px solid #222}section{border-bottom:1px solid #aaa;padding:5px 0}h3{margin-bottom:4px}p{margin:5px 0}</style></head><body>${body}</body></html>`);w.document.close();setTimeout(()=>w.print(),300)}
document.addEventListener('click',e=>{let t=e.target.closest('[data-ext]');if(!t)return;e.stopImmediatePropagation();let g=gang(),c=campaign(),d=t.dataset,v=g?.vehicles?.find(x=>x.id===d.id),f=g?.fighters?.find(x=>x.id===d.id);switch(d.ext){case 'new-vehicle':vehicleForm();break;case 'edit-vehicle':vehicleForm(v);break;case 'vehicle-detail':vehicleDetail(v);break;case 'delete-vehicle':confirmDelete('차량 삭제',`${esc(v.name)} 차량을 삭제할까요?`,()=>{g.vehicles=g.vehicles.filter(x=>x.id!==v.id);log(g,`${v.name} 차량을 삭제했습니다.`);save()});break;case 'add-vehicle-equipment':closeModal();formModal('차량 장비',field('name','장비 이름','','text','required')+field('cost','비용',0,'number','min="0"'),x=>{v.equipment.push({id:id(),name:x.name,cost:n(x.cost)});log(g,`${v.name}에 ${x.name} 장비를 추가했습니다.`);save()});break;case 'delete-vehicle-equipment':v.equipment=v.equipment.filter(x=>x.id!==d.sub);closeModal();save();break;case 'add-vehicle-damage':closeModal();formModal('차량 손상',field('name','손상 이름','','text','required')+textarea('notes','메모'),x=>{v.damages.push({id:id(),...x});log(g,`${v.name}에 손상을 기록했습니다.`);save()});break;case 'repair-vehicle':v.damages=v.damages.filter(x=>x.id!==d.sub);closeModal();log(g,`${v.name} 차량 손상을 수리했습니다.`);save();break;case 'new-tactic':formModal('전술 카드 추가',field('name','카드 이름','','text','required')+field('source','출처 / 세트')+textarea('effect','효과 메모'),x=>{g.tactics.push({id:id(),...x});log(g,`${x.name} 전술 카드를 추가했습니다.`);save()});break;case 'delete-tactic':g.tactics=g.tactics.filter(x=>x.id!==d.id);save();break;case 'copy-gang':cloneGang(g);break;case 'print-gang':printGang(g);break;case 'copy-fighter':{let copy=structuredClone(f);copy.id=id();copy.name+=' 사본';copy.equipment.forEach(x=>x.id=id());copy.effects.forEach(x=>x.id=id());g.fighters.push(copy);closeModal();log(g,`${f.name} 파이터를 복제했습니다.`);save();break}case 'fighter-note':closeModal();formModal('파이터 배경 이야기',textarea('backstory','배경 이야기',f.backstory||''),x=>{f.backstory=x.backstory;save()});break;case 'remove-effect':f.effects=f.effects.filter(x=>x.id!==d.sub);closeModal();save();break;case 'remove-skill':f.skills.splice(Number(d.sub),1);closeModal();save();break;case 'edit-gang-story':formModal('갱 이야기',textarea('value','이야기',g.backstory),x=>{g.backstory=x.value;save()});break;case 'edit-gang-private':formModal('개인 메모',textarea('value','메모',g.privateNotes),x=>{g.privateNotes=x.value;save()});break;case 'new-triumph':formModal('성과 기록',field('name','성과 이름','','text','required')+select('gangId','획득 갱',gangOptions('',true))+textarea('notes','메모'),x=>{c.triumphs.push({id:id(),...x});save()});break;case 'delete-triumph':c.triumphs=c.triumphs.filter(x=>x.id!==d.id);save();break;case 'edit-campaign-notes':formModal('캠페인 스토리',textarea('value','스토리',c.notes),x=>{c.notes=x.value;save()});break;case 'edit-house-rules':formModal('하우스 룰',textarea('value','규칙 메모',c.houseRules),x=>{c.houseRules=x.value;save()});break;case 'map-edit':editTerritory(c.territories.find(x=>x.id===d.id));break}},true);
render();
